const D = { hue: 210, energy: .6, speed: 1, density: .5, scale: 1, x: .5, y: .5, edge: .5, style: 'orient', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height), maxD = Math.max(width, height);
const clamp = (v,a,b) => v < a ? a : v > b ? b : v;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat; S.lastBeat = K.beat;

// pinwheel deflation: split a (1,2,sqrt5) triangle {r,l,s} into 5 congruent copies
function sub(t){
  const A0 = t.r, B0 = t.l, C0 = t.s;
  const cbx = C0[0]-B0[0], cby = C0[1]-B0[1];
  const ax = A0[0]-B0[0], ay = A0[1]-B0[1];
  const tt = (ax*cbx + ay*cby) / (cbx*cbx + cby*cby);
  const E = [B0[0]+tt*cbx, B0[1]+tt*cby];
  const M = (P0,Q0)=>[(P0[0]+Q0[0])*0.5,(P0[1]+Q0[1])*0.5];
  const Mab=M(A0,B0), Mae=M(A0,E), Meb=M(E,B0);
  return [
    {r:E,   l:A0,  s:C0},
    {r:Mae, l:Mab, s:A0},
    {r:Meb, l:B0,  s:Mab},
    {r:E,   l:Meb, s:Mae},
    {r:Mab, l:Mae, s:Meb}
  ];
}

const section = Math.floor(K.section || 0);
const depthDen = 2 + Math.round(clamp(P.density,0,1) * 2);            // 2..4
const cols = clamp(Math.round(3 / clamp(P.scale,0.5,2.2)), 1, 7);     // scale -> tile size
const seedCount = 4 * cols * cols;
const depthCap = Math.max(1, Math.floor(Math.log(6000 / seedCount) / Math.log(5)));
const depth = clamp(Math.min(depthDen, depthCap), 1, 4);
const hueBucket = Math.floor(((P.hue + section * 18) % 360) / 12);
const L = Math.min(Math.round(1.5 * maxD), 1500);
const key = [width, height, depth, cols, P.style, P.seed, hueBucket, P.edge.toFixed(2)].join('|');

if (S.key !== key){
  S.key = key;
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(L, L);
  S.buf.pixelDensity(1);
  S.L = L;
  const g = S.buf;
  g.colorMode(HSB, 360, 100, 100, 100);
  const st = P.style;
  const baseHue = (P.hue + section * 18) % 360;
  // paper / ground per style
  if (st === 'blueprint') g.background(212, 68, 16);
  else if (st === 'ink') g.background(40, 10, 88);
  else g.background(baseHue, 40, 9);
  // build seed triangles tiling the LxL square with 2:1 rectangles
  const rectW = L / cols, rectH = rectW / 2, rows = Math.max(1, Math.round(L / rectH));
  let tris = [];
  for (let i = 0; i < cols; i++){
    for (let j = 0; j < rows; j++){
      const x0 = i*rectW, y0 = j*rectH;
      const p00=[x0,y0], p10=[x0+rectW,y0], p11=[x0+rectW,y0+rectH], p01=[x0,y0+rectH];
      const v = (i + j + (P.seed % 2)) % 2;
      if (v === 0){ tris.push({r:p00,l:p10,s:p01}); tris.push({r:p11,l:p01,s:p10}); }
      else { tris.push({r:p10,l:p00,s:p11}); tris.push({r:p01,l:p11,s:p00}); }
    }
  }
  for (let d = 0; d < depth; d++){
    const nx = [];
    for (let k = 0; k < tris.length; k++){ const c = sub(tris[k]); nx.push(c[0],c[1],c[2],c[3],c[4]); }
    tris = nx;
  }
  const ew = (0.3 + P.edge * 2.1);
  const lightA = Math.PI * (0.25 + fr(7) * 0.5);
  for (let k = 0; k < tris.length; k++){
    const t = tris[k];
    const ang = Math.atan2(t.l[1]-t.r[1], t.l[0]-t.r[0]);         // orientation of long leg
    let deg = ang * 180 / Math.PI; if (deg < 0) deg += 360;
    const tileHue = (baseHue + deg) % 360;
    const jit = fr(k * 1.3 + 3);
    if (st === 'blueprint'){
      g.noFill();
      g.stroke(198, 22, 100, 62); g.strokeWeight(ew * 0.7);
    } else if (st === 'ink'){
      const shade = 0.15 + 0.6 * (0.5 + 0.5 * Math.cos(ang * 2));
      g.fill(38, 9, 88 - shade * 34);
      g.stroke(28, 24, 26, 78); g.strokeWeight(ew * (0.6 + 0.7 * jit));
    } else if (st === 'gem'){
      const lit = 0.5 + 0.5 * Math.cos(ang - lightA);
      g.fill(tileHue, 66, 34 + lit * 52);
      g.stroke((tileHue + 30) % 360, 18, 100, 70); g.strokeWeight(ew * 0.8);
    } else if (st === 'stained'){
      g.fill(tileHue, 78, 44 + jit * 32);
      g.stroke(baseHue, 30, 4, 92); g.strokeWeight(ew * 1.6);
    } else { // orient (default)
      g.fill(tileHue, 60, 52 + jit * 20);
      g.stroke((tileHue + 45) % 360, 34, 100, 50); g.strokeWeight(ew);
    }
    g.beginShape();
    g.vertex(t.r[0], t.r[1]); g.vertex(t.l[0], t.l[1]); g.vertex(t.s[0], t.s[1]);
    g.endShape(CLOSE);
  }
}

// ---- live: slow continuous rotation (motion floor) + glow ----
const cx = P.x * width, cy = P.y * height;
const rot = K.t * 0.018 * (0.4 + P.speed) + section * 0.15;
const frameDiag = Math.hypot(width, height);
const drawScale = Math.max(1, frameDiag / S.L * 1.03);
push();
translate(cx, cy);
rotate(rot);
scale(drawScale);
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.buf, -S.L * 0.5, -S.L * 0.5);
pop();

// additive breathing bloom (clk-driven, non-strobe, audio on top)
const baseHue2 = (P.hue + section * 18) % 360;
const swell = (K.swell != null ? K.swell : 0.5);
const bloom = 0.4 + 0.6 * swell + K.pulse * 0.4 + A.bass * 0.7;
push();
blendMode(ADD);
noStroke();
const gl = (0.04 + P.energy * 0.10) * bloom;
fill((baseHue2 + 26) % 360, 34, 100, clamp(gl * 100, 0, 15));
circle(cx, cy, u * (0.55 + 0.12 * Math.sin(K.t * 0.5)) * (1 + bloom * 0.15));
// a slow sweeping wedge of light for extra life
const nb = 5;
for (let i = 0; i < nb; i++){
  const a = rot * 1.3 + i * (Math.PI * 2 / nb);
  const rr = u * (0.18 + 0.22 * i / nb);
  const gx = cx + Math.cos(a) * rr, gy = cy + Math.sin(a) * rr;
  fill((baseHue2 + 60 + i * 22) % 360, 40, 100, clamp((0.05 + P.energy * 0.08 + A.treble * 0.4) * 100, 0, 10));
  circle(gx, gy, u * 0.18);
}
blendMode(BLEND);
pop();
